definitions.1056828183287ce3202e0dfafba7fde5a15d72aa:
DEFINE FUNCTION fn::recall_physical_read_fence($record: record) {
LET $table = meta::tb($record);
IF $table NOTINSIDE ['doc', 'source_head', 'source_publication_manifest'] { THROW 'publication:unsupported_physical_read_fence'; };
LET $bucket = string::slice(crypto::sha256(type::string($record)), 0, 3);
LET $id = type::thing('native_read_fence', string::concat($table, ':', $bucket));
LET $existing = (SELECT * FROM ONLY $id);
IF $existing != NONE AND !fn::recall_physical_read_fence_valid($existing) { THROW 'publication:invalid_native_read_fence'; };
UPSERT $id SET version = 1, nonce = <string> rand::uuid();
RETURN true;
} PERMISSIONS FULL

