definitions.1e4c544fc5eb3358486df34f6ec70d631b82b779:
DEFINE EVENT canonical_predicate_fence ON work_producer_origin WHEN $event INSIDE ['UPDATE', 'DELETE'] THEN { IF $event = 'DELETE' { IF $before.space_id != NONE { UPSERT type::thing('canonical_epoch', $before.space_id) SET space_id = $before.space_id, epoch = <string> rand::uuid(); }; } ELSE {
LET $origin_before = array::filter(object::entries($before), |$entry: any| $entry[0] != 'read_nonce');
LET $origin_after = array::filter(object::entries($after), |$entry: any| $entry[0] != 'read_nonce');
IF $origin_before != $origin_after {
IF $after.space_id != NONE { UPSERT type::thing('canonical_epoch', $after.space_id) SET space_id = $after.space_id, epoch = <string> rand::uuid(); };
IF $before.space_id != $after.space_id AND $before.space_id != NONE { UPSERT type::thing('canonical_epoch', $before.space_id) SET space_id = $before.space_id, epoch = <string> rand::uuid(); };
};
}; }

