LET $space = IF $event = 'DELETE' THEN $before.space_id ELSE $after.space_id END;
IF $space != NONE { UPSERT type::thing('canonical_epoch', $space) SET space_id = $space, epoch = <string> rand::uuid(); };
IF $event = 'UPDATE' AND $before.space_id != $after.space_id AND $before.space_id != NONE { UPSERT type::thing('canonical_epoch', $before.space_id) SET space_id = $before.space_id, epoch = <string> rand::uuid(); };
}

definitions.f5fa4988f309b69ec1ba986efefb05eecdc77052:
DEFINE EVENT erased_reference_fence ON source WHEN $event INSIDE ['CREATE', 'UPDATE', 'DELETE'] THEN { IF $event = 'DELETE' { fn::recall_reference_guard($before, false) } ELSE {
fn::recall_reference_guard($after, !('source' = 'system_event' AND $after.event_type = 'source.erased' AND $__recall_erasure_reservation != NONE));
IF $event = 'UPDATE' AND $before.space_id != $after.space_id { fn::recall_reference_guard($before, false) };
}; }

